import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in range(1, 6):
    try:
        dfs[i] = pd.read_csv(f"experiment_{i}_csv")
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[i].columns)}")
        print(f"Shape: {dfs[i].shape}")
        print(dfs[i].describe().round(2))
        if 'RecoveryScore' in dfs[i].columns:
            # Check correlations with RecoveryScore
            print(f"\nCorrelations with RecoveryScore:")
            for col in dfs[i].columns:
                if col != 'RecoveryScore' and dfs[i][col].dtype in ['float64','int64']:
                    r, p = stats.pearsonr(dfs[i][col], dfs[i]['RecoveryScore'])
                    print(f"  {col}: r={r:.3f}, p={p:.2e}")
    except Exception as e:
        print(f"Experiment {i} error: {e}")

# Combine all data to see overall patterns
all_data = pd.concat(dfs.values(), ignore_index=True)
print(f"\n=== ALL DATA COMBINED ===")
print(f"Shape: {all_data.shape}")
print(f"Columns: {list(all_data.columns)}")
print(all_data.describe().round(2))

# Check overall correlations with RecoveryScore
if 'RecoveryScore' in all_data.columns:
    print(f"\nOverall correlations with RecoveryScore:")
    for col in all_data.columns:
        if col != 'RecoveryScore' and all_data[col].dtype in ['float64','int64']:
            r, p = stats.pearsonr(all_data[col], all_data['RecoveryScore'])
            print(f"  {col}: r={r:.3f}, p={p:.2e}")

# Show unique values of any intervention columns
print("\n=== Unique intervention values ===")
for col in all_data.columns:
    if all_data[col].dtype in ['float64','int64'] and len(all_data[col].unique()) < 10:
        print(f"{col}: {sorted(all_data[col].unique())}")

