import pandas as pd
import numpy as np
from scipy import stats
import os

# Load all available experiments
dfs = {}
for exp_id in [1, 2, 3, 4, 5, 6, 8, 9]:
    path = f'experiment_{exp_id}_csv'
    try:
        # The variable experiment_X_csv holds the path
        dfs[exp_id] = pd.read_csv(path)
    except:
        pass

print("=== AVAILABLE EXPERIMENTS ===")
for k, v in dfs.items():
    print(f"\nExp {k}: {v.shape[0]} rows, columns: {list(v.columns)}")
    print(v.describe().round(2))

print("\n\n=== INTERVENTION DETECTION ===")
for k, v in dfs.items():
    do_cols = [c for c in v.columns if c.startswith('do_')]
    if do_cols:
        print(f"\nExp {k} has interventions: {do_cols}")
        for col in do_cols:
            unique_vals = v[col].unique()
            print(f"  {col}: unique values = {unique_vals}")
            if len(unique_vals) > 1:
                for val in unique_vals:
                    subset = v[v[col]==val]
                    if 'RecoveryScore' in subset.columns:
                        print(f"    Level {val}: n={len(subset)}, mean RecoveryScore={subset['RecoveryScore'].mean():.2f}, sd={subset['RecoveryScore'].std():.2f}")

print("\n\n=== CORRELATION ANALYSIS ===")
# Focus on experiments with RecoveryScore and other measures
for k in [3, 4, 5, 6, 8, 9]:
    if k in dfs and 'RecoveryScore' in dfs[k].columns:
        df = dfs[k]
        numeric_cols = df.select_dtypes(include=[np.number]).columns
        if len(numeric_cols) > 2:
            corr_with_recovery = df.corr(numeric_only=True)['RecoveryScore'].drop('RecoveryScore').sort_values(ascending=False)
            print(f"\nExp {k} correlations with RecoveryScore:")
            print(corr_with_recovery.round(3))
